from lib import *
L=[]
# ---- 1-1
L.append(lesson('1-1','AWS Organizations と SCP',[
('Organizations の基本構造',
f'''<h4>Organizations とは</h4><ul><li>{K('AWS Organizations')}：複数のAWSアカウントを一元管理するサービス。{K('管理アカウント')}（旧マスターアカウント）、{K('メンバーアカウント')}、{K('OU（組織単位）')}、{K('ルート')}で階層を作る</li><li>OUは最大5階層まで入れ子にできる。アカウントは常に1つの親（ルート or OU）にだけ属する</li><li>機能セットは{K('全機能（All features）')}と{K('一括請求のみ')}。SCPや委任管理者など統制機能を使うには全機能が必須</li></ul><h4>主な機能</h4><ul><li>{K('一括請求（Consolidated Billing）')}：全メンバーの料金を管理アカウントへ集約。ボリューム割引、RI/Savings Plansの割引共有が可能</li><li>{K('SCP')}：アカウントが使える権限の上限をガードレールとして設定</li><li>タグポリシー、バックアップポリシー、AIサービスのオプトアウトポリシー等の{K('管理ポリシー')}</li><li>AWSサービスとの統合（信頼されたアクセス）と{K('委任管理者')}</li></ul><h4>試験の引っ掛け</h4><ul><li>{T('管理アカウントには本番ワークロードを置かない')}：管理アカウントはSCPの対象外なので、最小限の用途（請求・組織管理）に限る</li><li>新規アカウントは組織内で作成すると{K('OrganizationAccountAccessRole')}が自動作成され、管理アカウントから引き受けられる（招待で参加したアカウントには自動では作られない）</li></ul>''',
[('SCPおよびタグポリシーなどの統制機能を利用するには、Organizationsを「全機能」で有効化する必要がある。',True,'一括請求のみのモードでは統制機能は使えません。全機能にする必要があります。'),
 ('OUは1階層のみで、入れ子にはできない。',False,'OUは最大5階層まで入れ子にできます。'),
 ('管理アカウントには本番ワークロードを置くのが推奨である。',False,'管理アカウントはSCPの対象外で影響範囲が大きいため、本番ワークロードは置かないのがベストプラクティスです。')]),
('SCP の仕組みと評価ロジック',
f'''<h4>SCPは「許可の上限」</h4><ul><li>{K('SCP（サービスコントロールポリシー）')}自体は権限を{T('付与しない')}。IAMポリシーが許可する範囲に対する{K('最大権限の境界（ガードレール）')}</li><li>実効権限 ＝ {K('SCP ∩ IAM（ID/リソースポリシー・権限境界）')}。どちらかが拒否・未許可なら不可</li><li>ルート→OU→アカウントの各階層で、{K('すべての階層で許可されている')}アクションだけが通る</li></ul><h4>拒否リスト方式と許可リスト方式</h4><table><tr><th>方式</th><th>内容</th></tr><tr><td>拒否リスト（deny list）</td><td>デフォルトの {K('FullAWSAccess')} SCPを残し、禁止したい操作に明示Denyを書く。運用が楽で推奨</td></tr><tr><td>許可リスト（allow list）</td><td>FullAWSAccessを外し、許可するサービスだけをAllowで列挙。厳格だが管理が重い</td></tr></table><h4>重要な適用範囲</h4><ul><li>{K('管理アカウントのユーザー/ロールには効かない')}</li><li>メンバーアカウントの{K('ルートユーザーにも効く')}</li><li>{K('サービスリンクロール')}には効かない</li><li>{K('リソースベースポリシーで他アカウントのプリンシパルに付与された権限')}は、そのプリンシパル側アカウントのSCPで制限される</li></ul>''',
[('SCPはIAMポリシーと同様にプリンシパルへ権限を付与できる。',False,'SCPは許可の上限を定めるだけで、権限を付与しません。IAM側の許可も必要です。'),
 ('SCPはメンバーアカウントのルートユーザーにも適用される。',True,'メンバーアカウントのルートユーザーはSCPの対象です（管理アカウントは対象外）。'),
 ('SCPは管理アカウントのIAMロールの操作も制限できる。',False,'管理アカウントにはSCPは適用されません。')]),
('SCP の設計パターンと条件キー',
f'''<h4>典型的なガードレール</h4><ul><li>{K('リージョン制限')}：{K('aws:RequestedRegion')}条件で許可リージョン以外を拒否。IAM・Organizations・CloudFront・Route 53などグローバルサービスは除外（NotAction）する</li><li>{K('セキュリティサービスの無効化禁止')}：CloudTrail停止、Config停止、GuardDuty無効化を拒否</li><li>{K('組織からの離脱禁止')}：organizations:LeaveOrganization を拒否</li><li>{K('ルートユーザー操作禁止')}：aws:PrincipalArn がルートの場合に拒否</li><li>{K('暗号化必須')}：暗号化なしのEBS/S3作成を拒否、特定インスタンスタイプ以外の起動を拒否</li><li>{K('aws:PrincipalOrgID')}：リソースポリシーで「自組織内のみ許可」と書く（アカウントID列挙より運用が楽）</li></ul><h4>判断のコツ</h4><ul><li>「個別アカウントに入れ替わり管理者がいても、全員に絶対許さない」→ {K('SCP')}</li><li>「開発者が自分で作るロールに権限の天井を設けたい」→ {K('IAM権限境界（Permissions Boundary）')}。SCPは組織側、権限境界はアカウント内の委任管理用</li><li>{T('SCPのDenyは条件付きでも強い')}：例外が必要なときは条件キーで管理ロールだけ除外する</li></ul>''',
[('特定リージョン以外の利用を禁止するには、SCPでaws:RequestedRegion条件を使うのが一般的である。',True,'リージョン制限の定番です。グローバルサービスはNotActionで除外します。'),
 ('リソースポリシーで自組織のアカウントだけにアクセスを許可するには、aws:PrincipalOrgID条件キーが使える。',True,'アカウントIDを列挙せず組織単位で許可できます。'),
 ('開発者が作成するIAMロールの権限の天井を、アカウント内で委任管理するにはSCPが最適である。',False,'その用途はIAM権限境界です。SCPは組織レベルのガードレールです。')]),
('委任管理者・信頼されたアクセス・ポリシー種別',
f'''<h4>委任管理者</h4><ul><li>多くのサービス（GuardDuty、Security Hub、Config、IAM Identity Center、Firewall Manager、CloudFormation StackSets等）は、Organizationsと統合し{K('信頼されたアクセス')}を有効化した上で{K('委任管理者アカウント')}を指定できる</li><li>目的：{K('管理アカウントを日常運用から切り離す')}。セキュリティ専用アカウントなどに管理を移す</li></ul><h4>Organizations の管理ポリシー</h4><table><tr><th>種類</th><th>用途</th></tr><tr><td>SCP</td><td>権限の上限</td></tr><tr><td>タグポリシー</td><td>タグキー・値の標準化（付与の強制ではなく、準拠評価。強制オプションあり）</td></tr><tr><td>バックアップポリシー</td><td>AWS Backupプランを組織全体に適用</td></tr><tr><td>AIサービスオプトアウト</td><td>AIサービスによるコンテンツ利用の拒否</td></tr><tr><td>RCP（リソースコントロールポリシー）</td><td>リソース側の権限上限（データ境界の実装など）</td></tr></table><ul><li>{T('RCPはリソースに対するアクセスの上限')}を設定。SCPがプリンシパル側、RCPがリソース側と覚える</li></ul>''',
[('GuardDutyなどのセキュリティサービスは、管理アカウント以外を委任管理者に指定できる。',True,'セキュリティ専用アカウントを委任管理者にするのが推奨構成です。'),
 ('タグポリシーはタグのないリソースの作成を常に自動で拒否する。',False,'基本は準拠評価です。作成拒否はサポート対象リソースで強制設定した場合に限られます。'),
 ('RCPはIAMプリンシパルに対する権限の上限を設定するポリシーである。',False,'RCPはリソースに対する権限の上限です。プリンシパル側はSCPです。')]),
]))
# ---- 1-2
L.append(lesson('1-2','Control Tower とマルチアカウント戦略',[
('なぜマルチアカウントか',
f'''<h4>マルチアカウント戦略の目的</h4><ul><li>{K('爆発半径の分離')}：障害・侵害・誤操作の影響を1アカウントに閉じ込める</li><li>{K('サービスクォータの分離')}：アカウント／リージョン単位のクォータを環境別に確保</li><li>{K('コスト可視化')}：アカウント単位で請求を分離</li><li>{K('権限・コンプライアンス境界')}：PCI対象環境などを独立させる</li></ul><h4>推奨OU構成（AWS推奨の例）</h4><table><tr><th>OU</th><th>用途</th></tr><tr><td>Security</td><td>ログアーカイブ、セキュリティツール（監査）アカウント</td></tr><tr><td>Infrastructure</td><td>ネットワーク（Transit Gateway等）、共有サービス</td></tr><tr><td>Workloads (Prod / Non-Prod)</td><td>本番／開発のワークロードアカウント</td></tr><tr><td>Sandbox</td><td>実験用。予算上限と厳しいSCP</td></tr><tr><td>Policy Staging / Suspended</td><td>ポリシー検証用／閉鎖予定アカウント</td></tr></table><h4>判断</h4><ul><li>「環境別」ではなく{K('ワークロード別 × 環境別')}にアカウントを分ける</li><li>{T('単一アカウント内でIAMだけで分離')}は、爆発半径・クォータ・請求の面で不足と判断される</li></ul>''',
[('マルチアカウント構成の利点には、爆発半径の限定と請求の分離が含まれる。',True,'どちらも主要な目的です。'),
 ('ログアーカイブアカウントは、通常Workloads OUに置く。',False,'ログやセキュリティ関連はSecurity OUに置くのが推奨です。'),
 ('Sandbox OUには本番並みの広い権限を与え、予算制限は設けない。',False,'Sandboxは予算上限と厳しいSCPで統制するのが一般的です。')]),
('Control Tower のランディングゾーン',
f'''<h4>Control Tower とは</h4><ul><li>{K('AWS Control Tower')}：Organizations、IAM Identity Center、Config、CloudTrail、Service Catalog等を組み合わせ、{K('ベストプラクティス準拠のマルチアカウント環境（ランディングゾーン）')}を自動構築・運用するサービス</li><li>作成されるもの：Security OU（{K('ログアーカイブアカウント')}と{K('監査アカウント')}）、Sandbox OU、組織CloudTrail、Config集約、IAM Identity Centerなど</li><li>{K('Account Factory')}：Service Catalogベースでアカウントを標準化して払い出す。{K('Account Factory for Terraform (AFT)')}やAccount Factory Customization (AFC)でカスタマイズ可能</li></ul><h4>ガードレール（コントロール）</h4><table><tr><th>種類</th><th>実装</th><th>動き</th></tr><tr><td>予防的</td><td>SCP</td><td>違反操作を拒否</td></tr><tr><td>発見的</td><td>AWS Config ルール</td><td>違反を検出（Dashboardに非準拠表示）</td></tr><tr><td>プロアクティブ</td><td>CloudFormation Hooks</td><td>デプロイ前にテンプレートを検査</td></tr></table><ul><li>{T('予防的=SCP、発見的=Config、プロアクティブ=CFn Hooks')}は頻出の対応表</li><li>ドリフト検知：ガードレールや構成が手動変更された場合に検出し、修復（再登録・更新）する</li></ul>''',
[('Control Towerの予防的ガードレールはAWS Configルールで実装される。',False,'予防的はSCP、発見的がConfigルールで実装されます。'),
 ('Control Towerのランディングゾーンには、ログアーカイブアカウントと監査アカウントが含まれる。',True,'Security OUに作成されます。'),
 ('プロアクティブコントロールは、CloudFormationテンプレートのデプロイ前に違反を検査する。',True,'CloudFormation Hooksで実装されます。')]),
('Control Tower と Organizations の使い分け',
f'''<h4>選択基準</h4><table><tr><th>状況</th><th>選択</th></tr><tr><td>新規にベストプラクティスの環境を素早く作りたい</td><td>Control Tower</td></tr><tr><td>既存のOrganizationsに統制を足したい</td><td>Control Towerで既存OU/アカウントを{K('登録（enroll）')}、または必要に応じ個別にSCP</td></tr><tr><td>独自の細かいガードレールを自作したい</td><td>Organizations SCP + Config + StackSets を直接構成</td></tr></table><h4>押さえどころ</h4><ul><li>Control Towerは{K('ホームリージョン')}を持ち、後から変更できない。ガバナンス対象リージョンは追加可能</li><li>Control Towerが管理するリソース（StackSetで作成されたConfigやロール等）を{T('手動で変更するとドリフト')}となる</li><li>既存アカウントは、前提条件を満たした上で個別に、またはOU単位で{K('登録（enroll）')}できる</li><li>追加で自作のカスタム統制が必要なら、{K('Customizations for AWS Control Tower (CfCT)')}や{K('AFT')}を使う</li></ul><h4>StackSets との関係</h4><ul><li>{K('CloudFormation StackSets')}は、Organizationsと統合した{K('サービス管理の権限')}で、OU指定により新規アカウントへ{K('自動デプロイ')}できる</li></ul>''',
[('Control Towerのホームリージョンは、構築後に自由に変更できる。',False,'ホームリージョンは後から変更できません。'),
 ('StackSetsをOrganizationsと統合すると、OUに追加された新しいアカウントへ自動的にスタックを展開できる。',True,'サービス管理の権限と自動デプロイを使います。'),
 ('Control Tower管理下のリソースを手動で変更すると、ドリフトとして検出されることがある。',True,'管理リソースの手動変更はドリフトの原因です。')]),
('AWS RAM とリソース共有',
f'''<h4>RAMとは</h4><ul><li>{K('AWS Resource Access Manager (RAM)')}：リソースをアカウント間（または組織・OU単位）で{K('コピーせず共有')}する。追加料金なし</li><li>共有できる主な例：{K('VPCサブネット')}、{K('Transit Gateway')}、{K('Route 53 Resolverルール')}、License Manager設定、Aurora DBクラスター、プライベートCA、Systems Manager OpsItem等</li><li>Organizationsで{K('RAMの共有を有効化')}すると、招待の承諾なしで組織内に共有される</li></ul><h4>VPC共有（共有サブネット）</h4><ul><li>ネットワークアカウントがVPCを所有し、{K('サブネットを他アカウントと共有')}。参加アカウントはそのサブネットにEC2/RDS等を起動できる</li><li>参加アカウントは自分のリソースを管理するが、{T('VPC、サブネット、ルートテーブル、TGWアタッチメントは所有者のみ変更可')}</li><li>メリット：VPC数・VPC間接続・NATの削減、{K('IP管理の集約')}。同一AZは物理AZ ID（use1-az1等）で揃える</li></ul><h4>注意</h4><ul><li>{T('S3やSQSなどはRAMではなく、リソースポリシーで共有')}する</li><li>Transit Gatewayは共有しても、各アカウントが{K('自分のVPCアタッチメント')}を作成する（承諾は自動承諾設定もあり）</li></ul>''',
[('RAMを使うと、VPCのサブネットを組織内の他アカウントと共有できる。',True,'VPC共有はRAMの代表例です。'),
 ('共有サブネットを利用する参加アカウントは、そのサブネットのルートテーブルを変更できる。',False,'ルートテーブルやサブネット自体は所有者のみ管理できます。'),
 ('S3バケットのアカウント間共有には、RAMの利用が必須である。',False,'S3はバケットポリシー等のリソースポリシーで共有します。')]),
]))
# ---- 1-3
L.append(lesson('1-3','IAM Identity Center とクロスアカウントアクセス',[
('IAM Identity Center による集中ID管理',
f'''<h4>IAM Identity Center（旧 AWS SSO）</h4><ul><li>{K('組織全体のワークフォース認証・認可')}を一元化。複数アカウントと業務アプリへのシングルサインオンを提供</li><li>{K('ID ソース')}は1つだけ選ぶ：Identity Centerディレクトリ（内蔵）／{K('AD Connector / AWS Managed Microsoft AD')}／{K('外部IdP（SAML 2.0、SCIMで自動プロビジョニング）')}</li><li>{K('許可セット（Permission Set）')}：IAMポリシーの集合。ユーザー/グループ×アカウント×許可セットを{K('割り当て')}ると、対象アカウントにIAMロール（AWSReservedSSO_...）が自動作成される</li><li>ユーザーはポータルからアカウントとロールを選び、{K('短期の認証情報')}で操作。IAMユーザーとアクセスキーの配布が不要になる</li></ul><h4>設計のコツ</h4><ul><li>割り当ては{K('個人ではなくグループ単位')}にする</li><li>{K('属性ベースアクセス制御（ABAC）')}：IdPの属性をセッションタグとして渡し、タグ条件でリソースへのアクセスを制御</li><li>Identity Centerは{K('1つのリージョン')}にインスタンスを持つ。{K('委任管理者')}を使えば管理アカウント外で運用可能</li><li>{T('アプリケーションのエンドユーザー（顧客）認証はCognito')}。Identity Centerは従業員向け</li></ul>''',
[('IAM Identity Centerでは、複数のIDソースを同時に有効化できる。',False,'IDソースは同時に1つだけ選択します。'),
 ('IAM Identity Centerに許可セットを割り当てると、対象アカウントにIAMロールが自動的に作成される。',True,'AWSReservedSSO_で始まるロールが作られます。'),
 ('Webアプリの一般消費者のサインアップ・サインインには、IAM Identity Centerが適している。',False,'顧客向けIDはAmazon Cognitoの領域です。')]),
('クロスアカウントアクセス（STS AssumeRole）',
f'''<h4>AssumeRoleの仕組み</h4><ul><li>ターゲットアカウントに{K('IAMロール')}を作り、{K('信頼ポリシー')}で「誰が引き受けられるか」を指定（プリンシパルにアカウントやロールを指定）</li><li>呼び出し側には{K('sts:AssumeRole を許可するIDポリシー')}が必要。{T('信頼ポリシーと呼び出し側の許可の両方が必要')}（同一アカウント内では片方で足りる場合があるが、クロスアカウントは両方必須）</li><li>STSが{K('一時的な認証情報')}（デフォルト1時間、ロールチェーンは最大1時間）を発行</li></ul><h4>関連機能</h4><table><tr><th>機能</th><th>用途</th></tr><tr><td>ExternalId</td><td>{K('混乱した代理（confused deputy）問題')}対策。サードパーティSaaSにロールを引き受けさせる時に信頼ポリシーへ条件として設定</td></tr><tr><td>aws:PrincipalOrgID</td><td>信頼ポリシーで自組織内のみに限定</td></tr><tr><td>MFA条件</td><td>aws:MultiFactorAuthPresent で引き受けにMFAを要求</td></tr><tr><td>SourceIdentity / セッションタグ</td><td>監査性の向上、ABAC</td></tr></table><ul><li>{K('Webフェデレーション/SAMLフェデレーション')}：AssumeRoleWithWebIdentity / AssumeRoleWithSAML</li></ul>''',
[('クロスアカウントのAssumeRoleでは、ロールの信頼ポリシーと呼び出し元側の許可の両方が必要になる。',True,'クロスアカウントでは両側の許可が必要です。'),
 ('サードパーティにロールを引き受けさせる際、confused deputy問題の対策としてExternalIdを使う。',True,'信頼ポリシーにExternalIdの条件を設定します。'),
 ('STSで発行される一時認証情報は、有効期限がなく失効させるまで使える。',False,'一時認証情報には有効期限があります。')]),
('リソースベースポリシーとクロスアカウント',
f'''<h4>2つの方式の違い</h4><table><tr><th>方式</th><th>動き</th><th>向く場面</th></tr><tr><td>ロール引き受け</td><td>呼び出し元は{K('自分のアイデンティティを一時的に手放し')}ターゲットのロールで動く</td><td>多数のサービスをまたぐ操作、監査をロール単位にしたい</td></tr><tr><td>リソースベースポリシー</td><td>呼び出し元は{K('元のアイデンティティのまま')}リソースにアクセス</td><td>S3、SQS、SNS、KMS、Lambda、Secrets Managerなど。ロールの切替が不要</td></tr></table><h4>押さえるポイント</h4><ul><li>S3にクロスアカウントで書き込む場合：バケットポリシーとIDポリシーの両方が必要（別アカウントのプリンシパルの場合）</li><li>{K('KMSキー')}は{K('キーポリシー')}が主。クロスアカウントではキーポリシーで許可し、利用側もIDポリシーで許可</li><li>{T('別アカウントから書き込まれたS3オブジェクトの所有者')}は書き込み側のままになる場合がある → {K('バケット所有者強制（BucketOwnerEnforced）')}のACL無効化で解決</li><li>Lambdaを別アカウントから呼ぶ：関数のリソースベースポリシーで許可</li></ul>''',
[('S3バケットポリシーでクロスアカウントを許可すれば、呼び出し元はロールを引き受けずに直接アクセスできる。',True,'リソースベースポリシーは元のアイデンティティのままアクセスできます。'),
 ('別アカウントから書き込まれたS3オブジェクトの所有権問題は、BucketOwnerEnforcedで解決できる。',True,'ACLを無効化し、バケット所有者が所有者となります。'),
 ('クロスアカウントでKMSキーを使うには、利用側のIDポリシーのみで足りる。',False,'キーポリシーでの許可が必須です。')]),
('ID フェデレーションと実務の判断',
f'''<h4>よくあるシナリオと答え</h4><table><tr><th>要件</th><th>答え</th></tr><tr><td>社内ADの従業員が複数アカウントへSSO</td><td>IAM Identity Center + AD（AD Connector / Managed AD / 外部IdP）</td></tr><tr><td>外部IdP（Entra ID、Okta）からのユーザー/グループ自動同期</td><td>{K('SCIM')}プロビジョニング</td></tr><tr><td>EC2上アプリが他アカウントのS3へアクセス</td><td>インスタンスプロファイルのロールが{K('ターゲットのロールをAssumeRole')}。アクセスキーは埋め込まない</td></tr><tr><td>オンプレのサーバーがAWSにアクセス</td><td>{K('IAM Roles Anywhere')}（X.509証明書で一時認証情報）／SSMハイブリッドアクティベーション</td></tr><tr><td>モバイルアプリのユーザーが自分のS3領域にアクセス</td><td>Cognito ID プール</td></tr></table><h4>引っ掛け</h4><ul><li>{T('長期のアクセスキーをアカウント間で配る')}選択肢はほぼ誤り</li><li>緊急時のため管理アカウントに{K('ブレークグラス（緊急用）')}アクセスを用意し、利用をアラート対象とする設計も出る</li></ul>''',
[('オンプレミスのサーバーがAWSリソースにアクセスする際、長期アクセスキーの代わりにIAM Roles Anywhereを使える。',True,'X.509証明書で一時認証情報を取得します。'),
 ('外部IdPのユーザーとグループをIAM Identity Centerへ自動同期するには、SCIMを使う。',True,'SCIMで自動プロビジョニングされます。'),
 ('他アカウントのS3へアクセスするEC2アプリには、IAMユーザーのアクセスキーをアプリへ埋め込むのが推奨される。',False,'インスタンスプロファイルとAssumeRoleによる一時認証情報が推奨です。')]),
]))
